  "content": "// Hand-written token cache. Previously generated from src/token.template.js
// via scripts/sync-tokens.mjs (one copy per token kind); folded back into a
// plain file so the race-condition fix can't drift between copies again and
// contributors aren't fighting a build step that rewrites this file under them.
//
// Both getAccessToken and getRefreshToken share this single implementation,
// each closing over its own private store.
function createTokenGetter() {
  const store = { cached: null, pendingFetch: null };

  return async function getToken(fetchToken, ttlMs = 50) {
    if (store.cached && store.cached.expiresAt > Date.now()) {
      return store.cached.value;
    }
    if (store.pendingFetch) {
      return store.pendingFetch;
    }
    store.pendingFetch = (async () => {
      const value = await fetchToken();
      store.cached = { value, expiresAt: Date.now() + ttlMs };
      store.pendingFetch = null;
      return value;
    })();
    return store.pendingFetch;
  };
}

export const getAccessToken = createTokenGetter();
export const getRefreshToken = createTokenGetter();
"
